import React from 'react';
import { Carousel } from './index';

const previews = {
  componentName: 'Carousel',
  importPath: 'components/Carousel',
  previews: [
    { name: '3D rig', description: "Merry-go-round: spinning horses under a striped canopy, from the RCT2 sprite.", render: () => <Carousel /> },
  ],
};

export default previews;

import React from 'react';
import { Stage, box, cyl, ball } from '../Stage';
import { buildPeep } from '../Guest';

// Merry-go-round modelled from the RCT2 sprite: a spinning platform of galloping
// horses under a striped conical canopy on a central pole. Horses bob as it
// turns; a couple carry peeps.
export function Carousel() {
  return (
    <Stage
      distance={6.5}
      targetY={1.1}
      build={(t, g) => {
        g.add(cyl(t, 0.5, 0.6, 0.4, 0x8a8f98, [0, 0.2, 0], { tex: 'concrete', repeat: [6, 1], rough: 0.9 })); // base

        const ride = new t.Group();
        g.add(ride);
        ride.add(cyl(t, 1.5, 1.5, 0.18, 0xf0d9a0, [0, 0.5, 0], { tex: 'plastic', repeat: [8, 1], rough: 0.5 })); // deck
        ride.add(cyl(t, 0.12, 0.12, 2.2, 0xd0d4da, [0, 1.6, 0], { tex: 'metal', metal: 0.8, rough: 0.3, seg: 20 })); // pole
        // striped canopy
        const canopy = cyl(t, 0.05, 1.7, 0.8, 0xd83a3a, [0, 2.35, 0], { tex: 'plastic', repeat: [12, 1], rough: 0.5, seg: 24 });
        ride.add(canopy);
        ride.add(cyl(t, 1.72, 1.72, 0.08, 0xf5e050, [0, 1.96, 0], { tex: 'plastic', repeat: [16, 1] })); // rim
        ride.add(ball(t, 0.16, 0xf5e050, [0, 2.8, 0], { metal: 0.5, rough: 0.3 })); // finial

        const horses: { grp: THREE.Group; ph: number }[] = [] as never;
        const N = 6;
        for (let i = 0; i < N; i++) {
          const a = (i / N) * Math.PI * 2;
          const hg = new t.Group();
          hg.position.set(Math.cos(a) * 1.05, 0.9, Math.sin(a) * 1.05);
          hg.rotation.y = -a + Math.PI / 2;
          hg.add(cyl(t, 0.02, 0.02, 1.1, 0xf5e050, [0, 0.35, 0], { tex: 'metal', metal: 0.9, rough: 0.2, seg: 8 })); // brass pole
          const body = 0xe8e2d8;
          hg.add(box(t, [0.5, 0.22, 0.18], body, [0, 0, 0], { rough: 0.6 })); // horse body
          hg.add(box(t, [0.16, 0.28, 0.14], body, [0.26, 0.16, 0], { rough: 0.6 })); // neck/head
          [-0.18, 0.18].forEach((zz) => {
            hg.add(box(t, [0.06, 0.24, 0.06], body, [0.18, -0.2, zz], { rough: 0.6 }));
            hg.add(box(t, [0.06, 0.24, 0.06], body, [-0.18, -0.2, zz], { rough: 0.6 }));
          });
          if (i % 2 === 0) {
            const p = buildPeep(t, { shirt: [0x3aa0e0, 0xe0a020][i % 2], seated: true });
            p.group.scale.setScalar(0.5);
            p.group.position.set(0, 0.1, 0);
            p.group.rotation.y = -Math.PI / 2;
            hg.add(p.group);
          }
          ride.add(hg);
          horses.push({ grp: hg, ph: a });
        }
        return (time) => {
          ride.rotation.y = time * 0.6;
          horses.forEach((hh) => (hh.grp.position.y = 0.9 + Math.sin(time * 3 + hh.ph) * 0.12));
        };
      }}
    />
  );
}

import React from 'react';
import { FerrisWheel } from './index';

const previews = {
  componentName: 'FerrisWheel',
  importPath: 'components/FerrisWheel',
  previews: [
    { name: '3D rig', description: "Ferris wheel with A-frame supports and gondolas that stay upright as they orbit.", render: () => <FerrisWheel /> },
  ],
};

export default previews;

import React from 'react';
import { Stage, box, cyl } from '../Stage';
import { buildPeep, SHIRTS, SKIN_TONES } from '../Guest';

// Ferris wheel modelled from the RCT2 sprite: A-frame supports, a spoked wheel
// that turns, and gondolas that stay upright as they orbit.
export function FerrisWheel() {
  return (
    <Stage
      distance={9}
      targetY={2.4}
      build={(t, g) => {
        const R = 2.4;
        const cy = 2.7;
        const STEEL = 0xd23a4a;
        // A-frame legs
        for (const sx of [-1, 1])
          for (const z of [-0.5, 0.5]) {
            const x0 = sx * 1.5;
            const L = Math.hypot(x0, cy);
            g.add(box(t, [0.12, L, 0.12], STEEL, [x0 / 2, cy / 2, z], { tex: 'metal', repeat: [1, 6], metal: 0.7, rough: 0.4, rotZ: Math.atan2(cy, -x0) - Math.PI / 2 }));
          }
        g.add(cyl(t, 0.12, 0.12, 1.1, 0x33343a, [0, cy, 0], { rotX: Math.PI / 2, tex: 'metal', metal: 0.8, rough: 0.3, seg: 16 })); // axle

        const wheel = new t.Group();
        wheel.position.set(0, cy, 0);
        g.add(wheel);
        for (const z of [-0.45, 0.45]) {
          const ring = new t.Mesh(new t.TorusGeometry(R, 0.06, 10, 40), new t.MeshStandardMaterial({ color: STEEL, metalness: 0.7, roughness: 0.4 }));
          ring.position.z = z;
          ring.castShadow = true;
          wheel.add(ring);
        }
        const N = 8;
        for (let i = 0; i < N; i++) {
          const a = (i / N) * Math.PI * 2;
          g.add; // spokes both planes
          [-0.45, 0.45].forEach((z) => wheel.add(box(t, [0.04, R * 2, 0.04], 0xe8e8ee, [0, 0, z], { rotZ: a, metal: 0.6, rough: 0.4 })));
        }

        const cols = [0x2f6fd0, 0xe0a020, 0x2e9e54, 0xd23a4a];
        const gondolas = [];
        for (let i = 0; i < N; i++) {
          const gd = new t.Group();
          gd.add(box(t, [0.5, 0.12, 0.5], 0x33343a, [0, -0.28, 0], { tex: 'metal', metal: 0.6, rough: 0.4 })); // floor
          gd.add(box(t, [0.5, 0.4, 0.5], cols[i % 4], [0, 0, 0], { tex: 'plastic', repeat: [2, 1], rough: 0.4, opacity: 0.96 })); // cabin
          gd.add(cyl(t, 0.36, 0.36, 0.14, cols[i % 4], [0, 0.3, 0], { tex: 'plastic', seg: 8, rough: 0.4 })); // roof
          const p = buildPeep(t, { skin: SKIN_TONES[i % SKIN_TONES.length], shirt: SHIRTS[i % SHIRTS.length], seated: true });
          p.group.scale.setScalar(0.42);
          p.group.position.y = -0.28;
          gd.add(p.group);
          g.add(gd);
          gondolas.push(gd);
        }
        return (time) => {
          wheel.rotation.z = time * 0.4;
          gondolas.forEach((gd, i) => {
            const a = (i / N) * Math.PI * 2 + wheel.rotation.z;
            gd.position.set(Math.cos(a) * R, cy + Math.sin(a) * R, 0);
            gd.rotation.z = 0;
          });
        };
      }}
    />
  );
}

import React from 'react';
import { Teacups } from './index';

const previews = {
  componentName: 'Teacups',
  importPath: 'components/Teacups',
  previews: [
    { name: '3D rig', description: "Spinning tea-cups flat ride: a turntable of cups that each spin on their own axis.", render: () => <Teacups /> },
  ],
};

export default previews;

import React from 'react';
import { Stage, cyl, box, ball } from '../Stage';
import { buildPeep, SHIRTS, SKIN_TONES } from '../Guest';

// Spinning tea-cups (a rotating-platform flat ride): a big turntable carrying
// four cups that each spin on their own axis while orbiting the centre.
export function Teacups() {
  return (
    <Stage
      distance={5.5}
      targetY={0.7}
      build={(t, g) => {
        g.add(cyl(t, 1.7, 1.8, 0.3, 0x8a8f98, [0, 0.15, 0], { tex: 'concrete', repeat: [10, 1], rough: 0.9, seg: 28 }));
        const deck = new t.Group();
        g.add(deck);
        deck.add(cyl(t, 1.6, 1.6, 0.14, 0xe8d9b0, [0, 0.37, 0], { tex: 'plastic', repeat: [10, 1], rough: 0.5, seg: 28 }));
        const cupCols = [0xd23a4a, 0x2f6fd0, 0x2e9e54, 0xe0a020];
        const cups = [];
        for (let i = 0; i < 4; i++) {
          const a = (i / 4) * Math.PI * 2;
          const cup = new t.Group();
          cup.position.set(Math.cos(a) * 0.95, 0.44, Math.sin(a) * 0.95);
          const col = cupCols[i];
          cup.add(cyl(t, 0.42, 0.3, 0.42, col, [0, 0.25, 0], { tex: 'plastic', repeat: [8, 1], rough: 0.4, seg: 24 }));
          cup.add(cyl(t, 0.44, 0.44, 0.05, 0xffffff, [0, 0.47, 0], { rough: 0.4, seg: 24 }));
          cup.add(cyl(t, 0.3, 0.3, 0.06, 0xffffff, [0, 0.05, 0], { seg: 20 }));
          const handle = new t.Mesh(new t.TorusGeometry(0.12, 0.03, 8, 14), new t.MeshStandardMaterial({ color: 0xffffff, roughness: 0.4 }));
          handle.rotation.y = Math.PI / 2;
          handle.position.set(0.44, 0.28, 0);
          cup.add(handle);
          const p = buildPeep(t, { skin: SKIN_TONES[i % SKIN_TONES.length], shirt: SHIRTS[(i + 4) % SHIRTS.length], seated: true, expression: 'surprised' });
          p.group.scale.setScalar(0.4);
          p.group.position.y = 0.12;
          cup.add(p.group);
          deck.add(cup);
          cups.push(cup);
        }
        return (time) => {
          deck.rotation.y = time * 0.7;
          cups.forEach((c, i) => (c.rotation.y = time * (2.4 + i * 0.3)));
        };
      }}
    />
  );
}

import React from 'react';
import { BumperCars } from './index';

const previews = {
  componentName: 'BumperCars',
  importPath: 'components/BumperCars',
  previews: [
    { name: '3D rig', description: "Dodgems: a fenced arena with a powered ceiling grid and four darting cars.", render: () => <BumperCars /> },
  ],
};

export default previews;

import React from 'react';
import { Stage, box, cyl, ball } from '../Stage';
import { buildPeep, SHIRTS, SKIN_TONES } from '../Guest';

// Bumper cars (dodgems) modelled from the RCT2 sprite: a fenced arena with a
// powered ceiling grid and four rounded cars darting about, each with a driver.
export function BumperCars() {
  return (
    <Stage
      distance={6.5}
      targetY={0.8}
      build={(t, g) => {
        const A = 2.4;
        g.add(box(t, [A + 0.4, 0.15, A + 0.4], 0x3a3f48, [0, 0.07, 0], { tex: 'metal', repeat: [8, 8], metal: 0.5, rough: 0.5 }));
        // low walls
        [-1, 1].forEach((s) => {
          g.add(box(t, [A + 0.4, 0.4, 0.12], 0xd23a4a, [0, 0.3, (s * (A + 0.4)) / 2], { tex: 'plastic', repeat: [8, 1], rough: 0.5 }));
          g.add(box(t, [0.12, 0.4, A + 0.4], 0xe0e0e0, [(s * (A + 0.4)) / 2, 0.3, 0], { tex: 'plastic', repeat: [8, 1], rough: 0.5 }));
        });
        // ceiling grid + posts
        [-1, 1].forEach((sx) => [-1, 1].forEach((sz) => g.add(cyl(t, 0.05, 0.05, 1.9, 0x2b2b30, [(sx * A) / 2, 1.0, (sz * A) / 2], { tex: 'metal', metal: 0.6, rough: 0.4, seg: 8 }))));
        g.add(box(t, [A, 0.06, A], 0x23242a, [0, 1.95, 0], { tex: 'metal', repeat: [10, 10], metal: 0.6, rough: 0.5, opacity: 0.9 }));
        for (let i = -2; i <= 2; i++) g.add(box(t, [A, 0.02, 0.03], 0x33343a, [0, 1.9, (i * A) / 5], { metal: 0.5 }));

        const cols = [0xe0201a, 0x2f6fd0, 0x2e9e54, 0xe0a020];
        const cars = [];
        for (let i = 0; i < 4; i++) {
          const car = new t.Group();
          car.add(box(t, [0.5, 0.18, 0.7], 0x111116, [0, 0.05, 0], { tex: 'metal', metal: 0.5, rough: 0.5 })); // rubber skirt
          car.add(box(t, [0.42, 0.28, 0.5], cols[i], [0, 0.28, -0.02], { tex: 'plastic', repeat: [2, 1], rough: 0.35 })); // body
          car.add(box(t, [0.34, 0.12, 0.2], 0x111116, [0, 0.36, 0.18], { rough: 0.7 })); // dash
          car.add(cyl(t, 0.02, 0.02, 1.6, 0x777, [0, 1.1, -0.15], { metal: 0.6, rough: 0.4, seg: 6 })); // pole
          car.add(ball(t, 0.05, 0x66e0ff, [0, 1.9, -0.15], { emissive: 0x2288aa })); // contact
          const p = buildPeep(t, { skin: SKIN_TONES[i % SKIN_TONES.length], shirt: SHIRTS[i], seated: true });
          p.group.scale.setScalar(0.42);
          p.group.position.set(0, 0.16, -0.02);
          car.add(p.group);
          g.add(car);
          cars.push(car);
        }
        const lim = A / 2 - 0.4;
        return (time) => {
          cars.forEach((c, i) => {
            const t2 = time * (0.8 + i * 0.15) + i * 1.7;
            const x = Math.sin(t2 * 1.1) * lim;
            const z = Math.cos(t2 * 0.9 + i) * lim;
            const nx = Math.cos(t2 * 1.1) * 1.1 * lim;
            const nz = -Math.sin(t2 * 0.9 + i) * 0.9 * lim;
            c.position.set(x, 0.1, z);
            c.rotation.y = Math.atan2(nx, nz);
          });
        };
      }}
    />
  );
}

import React from 'react';
import { PirateShip } from './index';

const previews = {
  componentName: 'PirateShip',
  importPath: 'components/PirateShip',
  previews: [
    { name: '3D rig', description: "Swinging pirate ship on a pivot arm between two towers.", render: () => <PirateShip /> },
  ],
};

export default previews;

import React from 'react';
import { Stage, box, cyl } from '../Stage';
import { buildPeep, SHIRTS, SKIN_TONES } from '../Guest';

// Swinging pirate ship modelled from the RCT2 sprite: a boat hull on a pivot
// arm between two A-frame towers, swinging back and forth with riders aboard.
export function PirateShip() {
  return (
    <Stage
      distance={8}
      targetY={1.6}
      build={(t, g) => {
        const pivotY = 3.0;
        const STEEL = 0x8790a0;
        // towers
        [-1, 1].forEach((s) => {
          [-0.6, 0.6].forEach((z) => {
            const x0 = s * 1.4;
            const L = Math.hypot(x0, pivotY);
            g.add(box(t, [0.14, L, 0.14], STEEL, [x0 / 2, pivotY / 2, z], { tex: 'metal', repeat: [1, 6], metal: 0.6, rough: 0.4, rotZ: Math.atan2(pivotY, -x0) - Math.PI / 2 }));
          });
        });
        g.add(cyl(t, 0.1, 0.1, 1.4, 0x33343a, [0, pivotY, 0], { rotX: Math.PI / 2, metal: 0.8, rough: 0.3, seg: 14 }));

        const swing = new t.Group();
        swing.position.set(0, pivotY, 0);
        g.add(swing);
        swing.add(box(t, [0.1, 2.4, 0.1], STEEL, [0, -1.2, 0], { tex: 'metal', metal: 0.6, rough: 0.4 })); // arm
        const boat = new t.Group();
        boat.position.y = -2.4;
        swing.add(boat);
        const HULL = 0x8a3f1a;
        boat.add(box(t, [2.4, 0.5, 0.9], HULL, [0, 0, 0], { tex: 'wood', repeat: [8, 2], rough: 0.7 }));
        boat.add(box(t, [2.0, 0.4, 0.8], 0x5a2a10, [0, 0.35, 0], { tex: 'wood', repeat: [8, 1], rough: 0.7 })); // upper deck rim
        // upswept ends
        [-1, 1].forEach((s) => boat.add(box(t, [0.5, 0.7, 0.9], HULL, [s * 1.25, 0.3, 0], { tex: 'wood', repeat: [2, 2], rough: 0.7, rotZ: s * 0.6 })));
        boat.add(cyl(t, 0, 0.18, 0.4, 0xe0c040, [1.5, 0.5, 0], { metal: 0.5, rough: 0.3, seg: 6 })); // dragon head-ish prow
        // riders
        for (let i = 0; i < 5; i++) {
          const p = buildPeep(t, { skin: SKIN_TONES[i % SKIN_TONES.length], shirt: SHIRTS[i % SHIRTS.length], seated: true, expression: 'surprised' });
          p.group.scale.setScalar(0.42);
          p.group.position.set(-0.8 + i * 0.4, 0.28, 0);
          boat.add(p.group);
        }
        return (time) => {
          swing.rotation.z = Math.sin(time * 1.1) * 0.9;
        };
      }}
    />
  );
}
